out=[]
def add(q,stem,values,reasons,ans,sol,knowledge,cid,labels,disc=None,conditions=None,figure=False,calc=True,steps=2,load=1,diff=2,cites=None):
 r=ini[q];s=sel[q];assert len(values)==len(reasons)==5
 out.append(dict(question_id=q,source_sha256=r['source_sha256'],stem=stem,summary=stem,conditions=conditions or {'判断対象':knowledge,'原典確認':'図・式・全5候補を29保存画像で確認。rawの数式欠落と演算子誤認は別校正JSONで扱う。'},choices={str(i):dict(value=v,verdict='適切' if i==ans else '不適切',reason=w) for i,(v,w) in enumerate(zip(values,reasons),1)},figures='原典の木・道路接続・構文経路・矢印を画像確認。教材では独自の構造表現で説明し原図転載なし。' if figure else '設問固有図なし。5候補と指数・記号を画像確認。',ambiguity='',evidence=['extracted/pages/'+s['source_file'].split('/')[1]+'/basic/page_%03d.png'%n for n in range(int(s['source_page']),int(s['source_page_end'])+1)],core_concept=stem,required_knowledge=knowledge,solution=sol,answer_reason=sol,independent_answer=r['answer_initial'],independent_solution_note='公式前の初回21解答を不変JSONに保存。'+r['reason'],learning_points='定義した対象量、演算順序、保存条件を固定し、途中状態と候補の違いを比較する。',theory_references=labels,discipline_id=disc or s['discipline_id'],concept_id=cid,cross_concepts=[],classification_reason='原典の中心は'+knowledge+'である。一般語の一致でなく実際の解法から学習分野を判断する。',calculation=str(calc).lower(),figure=str(figure).lower(),law='false',evaluation=dict(knowledge_novelty='1',reasoning_steps=str(steps),calculation_load=str(load),figure_reading='2' if figure else '0',difficulty=str(diff),difficulty_reason='物理専攻に既知の数学と新しいデータ表現を対応させる。'+('複数段の図・式・状態の追跡を要する。' if steps>=3 else '定義から短い計算又は反例を構成する。')),citations=cites or [],foundationality='high',transferability='high'))
add('H23-REG-BASIC-2-1','32ビットのIPv4アドレスを上位から8ビットずつ10進表示へ変換する。',['172.31.192.168','172.31.168.192','172.31.255.255','192.168.31.172','192.168.172.31'],['8ビット塊の前後を入れ替えている。','前後の塊と中央の順序が違う。','全ビット1の塊はなく255にはならない。','192、168、31、172を上位から並べている。','最後の31と172が逆である。'],4,'11000000=192、10101000=168、00011111=31、10101100=172である。原典32ビットをこの順に分割し192.168.31.172、4となる。ビットの順と表示基数を同時に変えない。','2進位取りと8ビット塊の順序。','concept_019',['theory:information:radix','theory:discrete:bitcount'],conditions={'ビット列':'11000000101010000001111110101100','区切り':'11000000|10101000|00011111|10101100'})
add('H24-REG-BASIC-2-5','最小値と最大値の更新をelseで結んだ走査の不変条件と失敗例を判定する。',['min常に最小・max常に最大でない','min常に最小・max失敗する場合あり','min失敗の場合あり・max常に最大でない','minもmaxも失敗の場合あり','min失敗の場合あり・max常に最大'],['1,2の順ならmax=2となるので常に失敗ではない。','minの更新は常に行われ、maxはelseで初回等を飛ばす場合がある。','minは各接頭列の最小を保持する。maxも成功例がある。','minは常に正しいので前半が違う。','minは正しくmaxは失敗例があるので両方違う。'],2,'min=1000から、より小さい値を毎回取り込むため、minは走査済みの最小値である。max更新は最小更新をしなかったときだけ行う。例えば入力2,1では最小更新を続けてmax=0となるが、1,2ならmax=2となる。minは常に最小、maxは失敗する場合があり2である。','0<a_i<1000、min初期1000、max初期0、elseによる排他的更新。','algorithm_scan_invariants',['theory:discrete:invariants'],calc=False)
add('H25-REG-BASIC-2-1','二値ランプの個数が4から8へ増えたときの状態数の倍率を求める。',['2倍','4倍','8倍','16倍','32倍'],['ランプ個数の比であって状態数の比ではない。','2個増加の倍率であり今回は4個増える。','3個増加の倍率である。','2の8乗を2の4乗で割ると16である。','5個増加の倍率である。'],4,'独立な二値の選択をn個並べると2のn乗通りである。8個なら256、4個なら16なので256/16=16、4である。ランプの種類が複数あっても設問の各位置の状態はON/OFFの二値である。','積の法則と二値状態の全組合せ。','discrete_state_counts',['theory:discrete:bitcount'])
add('H25-REG-BASIC-2-2','道路距離の最短施設への登録を、同距離で複数登録する条件も含めて数える。',['a>b>c','a=b>c','a=b=c','b>a=c','b>a>c'],['Bの人数がAより多いので逆である。','A3とB4は等しくない。','三施設の人数は3,4,2で異なる。','A3とC2は等しくない。','B4>A3>C2である。'],5,'各利用者から施設A,B,Cへの最短距離を求める。uは(2,2,8)、vは(5,5,6)、wは(5,4,4)、xは(3,3,3)である。したがってu,vはA/B、wはB/C、xは全施設へ登録され、a=3,b=4,c=2。5である。最短距離の同点を一施設だけへ割り当てない。','重み付き道路網の最短距離と同点の複数登録。','network_path',['theory:network:shortest'],figure=True,steps=3,load=2,diff=3,conditions={'全辺':'Au2、uB2、uv3、AB1、Ax3、Bx3、Bw4、xw3、vw2、vC6、wC4、xC3。','利用者':'u,v,w,x各1人。同距離なら全施設へ登録。'})
add('H26-REG-BASIC-2-1','二機械の部品加工を、機械順と部品順の二種類の先行制約でアロー図へ割り当てる。',['Aq,Bp,Ar,Bq','Aq,Bp,Bq,Ar','Aq,Ar,Bp,Bq','Bp,Aq,Bq,Ar','Bp,Aq,Ar,Bq'],['A列とB列の先行順、AqからBqのダミー制約に合う。','BqとArを入れ替えたためBpとBqの先行を保証できない。','ApからArがAqと並行になりA機械の順序に反する。','Aqが終了していなくてもBpの後にBqを開始でき、部品qのA→B順を保証しない。','Aqが終了していなくてもBpの後にArを開始でき、A機械のq→r順を保証しない。'],1,'Apの後にAqとBpが並行し、Aqの後にAr、AqとBpの両方が終わった後にBqを開始する。ArとBqの両方が終わってBrが始まる。よってアAq・イBp・ウAr・エBq、1である。ダミーは時間を要する実加工でなく先行関係を追加する。','機械ごとのp→q→rと部品ごとのA→Bという先行制約。','concept_012',['theory:discrete:precedence'],disc='basic_1_2',figure=True,calc=False,steps=3,diff=3)
add('H26-REG-BASIC-2-5','構文図の迂回と繰返し経路から生成できない文字列を選ぶ。',['a2b3c','x98y','w','p5q','abc45fg'],['a2とb3の二反復の後にcで終わる経路がある。','xの後に数字を二回通りyで終われる。','上側の迂回で最後の英字だけを通れる。','p5の一反復と最終qで生成できる。','中間の連続英字ab等を通る経路がなく生成できない。'],5,'Lを英字、Dを数字と書くと、下側の反復はLの後にDを1回以上通る単位、最後にはLを1回通る。上側で反復を飛ばすこともでき、言語は(LD+)の0回以上反復の後Lである。5は英字同士の連続を含みこの構文で生成できない。','構文図の順方向・戻り・迂回を反復と空反復へ対応させる。','concept_021',['theory:information:grammar','theory:discrete:syntax'],figure=True,calc=False)
add('H27-REG-BASIC-2-6','左右の部分木と根の演算から算術木を中置式へ読み戻す。',['(3−2)×(5−1)','5−1−3×2','3×2−5−1','3×2−(5−1)','3×2−5×1'],['根を掛算とする式で原典の減算根と違う。','左と右の部分式が逆である。','減算の左結合で(3×2−5)−1となり右部分木が違う。','左部分木3×2から右部分木5−1を引く構造に合う。','右部分木は乗算でなく減算である。'],4,'根は減算、左の子は乗算3×2、右の子は減算5−1である。よって3×2−(5−1)、4。葉だけを左から並べると括弧で指定する構造を失う。','算術木の左右順と演算子の優先・結合。','expression_tree_postorder',['theory:discrete:expression'],disc='basic_2_0',figure=True,calc=False)
def ipv6(q,exp,ans):
 vals=['2の'+str(x)+'乗倍' for x in exp]
 reasons=['IPv6とIPv4のビット長の差は96であり、この指数ではない。' if i!=ans else '128−32=96ビットの差に対応する。' for i in range(1,6)]
 add(q,'IPv4とIPv6のビット長から表現可能なアドレス総数の倍率を求める。',vals,reasons,ans,'IPv4は4×8=32ビット、IPv6は8×16=128ビット。全ビット列数の比は2の128乗/2の32乗=2の96乗である。予約・用途による割当の割合でなく表現可能な全列を数える。','nビットの全列2のn乗と、指数の差による状態数の比。','discrete_state_counts',['theory:discrete:bitcount'],cites=['rfc4291_addresses'])
ipv6('H28-REG-BASIC-2-6',[8,16,32,64,96],5);ipv6('R04-REG-BASIC-2-6',[4,16,32,96,128],4)
add('H29-REG-BASIC-2-3','試し割りで素数を判定する流れ図の継続条件と割り切れ判定を決める。',['I≥√N・IがNで割り切れる','I≥√N・NがIで割り切れない','I≥√N・NがIで割り切れる','I≤√N・NがIで割り切れない','I≤√N・NがIで割り切れる'],['継続範囲が逆で割り算の向きも逆である。','範囲と非素数へ進む判定が逆である。','範囲が逆でN=9等を正しく調べられない。','割り切れない時に非素数と出すので逆である。','2から平方根まで調べ、割り切れるなら非素数である。'],5,'合成数N=uvでは片方の因子が√N以下である。I=2からI≤√Nの間にN%I=0を調べ、真なら非素数、偽ならIを増やす。範囲を越えたら素数である。5となる。平方根が整数のときも含めるため≤が必要である。','因子対の平方根境界、継続判定、割り切れの向き。','algorithm_scan_invariants',['theory:discrete:invariants'],figure=True,calc=False)
add('H30-REG-BASIC-2-5','乗除を加算より先に行う中置式を後置記法へ変換する。',['ab×cd÷+','ab×c÷d+','abc×÷d+','abc+d÷×','abcd×÷+'],['左右の部分式ab×とcd÷を終えて根の+を出す。','(a×b)÷c+dとなり除算の対象が違う。','a÷(b×c)+dとなり括りが違う。','a×((b+c)÷d)となり加算対象が違う。','a+b÷(c×d)となり根以下の構造が違う。'],1,'対象はa×b+c÷dである。左部分式a×bはab×、右部分式c÷dはcd÷となる。両者を加える根を最後に置けばab×cd÷+、1である。','算術木の左・右・根の後行順走査と演算優先。','expression_tree_postorder',['theory:discrete:expression'],disc='basic_2_0',figure=True,calc=False)
add('H30-REG-BASIC-2-6','三集合の包除原理から和集合の補集合の要素数を求める。',['385','412','420','480','488'],['与えた交差数の包除と全体900からの差引きに合わない。','和集合488の補集合は900−488=412である。','三重交差等の補正を正しく扱った412とは異なる。','三重交差の加算を落とした等の誤りであり412ではない。','488は和集合の数であり問う補集合ではない。'],2,'和集合の数は300+180+128−60−43−26+9=488である。原典では和集合全体へ上線が付いており、その補集合を問う。全体900から引いて412、2となる。','三集合の重複補正と補集合の分母。','set_inclusion_exclusion',['theory:information:sets','theory:discrete:inclusion'],conditions={'数値':'|U|900、|A|300、|B|180、|C|128、|A∩B|60、|A∩C|43、|B∩C|26、三重9。','対象':'上線はA∪B∪C全体の補集合である。'},cites=['mit_discrete2015'])
add('R01-REG-BASIC-2-2','同じ二分探索木を作る挿入順を、部分木の祖先が先に入る条件から選ぶ。',['8,5,7,12,3,10,6','8,5,7,10,3,12,6','8,5,6,12,3,10,7','8,5,3,10,7,12,6','8,5,3,12,6,10,7'],['12を10より、7を6より先に入れ、根8と左根5も維持する。','10が12より先なので右部分木の根が10になる。','6が7より先なので5の右部分木の根が6になる。','10が12より先なので右部分木が変わる。','6が7より先なので左側部分木が変わる。'],1,'原典の根8、左5、右12、5の左右3/7、7の左6、12の左10を保つ。挿入順は親を子より先にし、別枝は前後してよい。1だけが12より前に10を置かず、7より前に6を置かない。','二分探索木の大小分岐と親子の挿入先行。','binary_search_tree_order',['theory:discrete:bst'],disc='basic_2_0',figure=True,calc=False,cites=['princeton_bst'])
add('R01-REG-BASIC-2-6','スタック操作の途中状態を追って最後のPOPの戻り値を求める。',['1','2','3','4','5'],['1は最後にスタックへ残る底の値である。','取り出し列4,3,5,2の最後である。','2回目のPOPで既に取り出されている。','1回目のPOPの値である。','最後から2回目のPOPの値である。'],2,'底から[1,2,3,4]となりPOPで4と3を除く。[1,2]へ5をPUSHし、POPで5、最後のPOPで2が返る。残る1と最後に返った2を区別し2を選ぶ。','後入れ先出し、PUSH/POPの状態と戻り値。','stack',['theory:discrete:stack'],calc=False)
def bezout(q,ab,triples,ans,sol):
 vals=[str(t) for t in triples];reasons=[]
 for i,(g,x,y) in enumerate(triples,1):
  reasons.append('指定行列の第二行と最大公約数が全て一致する。' if i==ans else '指定する係数行又は最大公約数が違う。線形和は'+str(ab[0]*x+ab[1]*y)+'となるが、gとの一致だけで指定行列の行とは限らない。')
 add(q,'拡張ユークリッド互除法の行列積から最大公約数と指定係数を求める。',vals,reasons,ans,sol,'割り算の余り、(0,1;1,−q)の行変換、Bézout係数。','extended_euclid_matrix',['theory:information:euclid','theory:discrete:extended'],steps=3,load=2,diff=3,cites=['mit_discrete2015'])
bezout('R01-RET-BASIC-2-2',(108,57),[(6,-1,2),(6,1,-2),(6,1,2),(3,9,-17),(3,-10,19)],4,'余り51,6,3,0からgcdは3。商1,1,8の変換行列を順に左から積むと(−1,2;9,−17)となる。指定第二行は9,−17で108×9−57×17=3、4である。5も線形和3を満たす別のBézout解だが、指定行列の第二行ではない。')
bezout('R06-REG-BASIC-2-5',(104,65),[(5,2,-3),(5,-3,5),(8,3,-3),(13,2,-3),(13,-3,5)],4,'余り39,26,13,0からgcdは13。商1,1,1の変換T=(0,1;1,−1)に対しTの3乗=(−1,2;2,−3)。指定第二行2,−3は104×2−65×3=13で4である。5の−3,5も線形和13だが指定行ではない。')
add('R03-REG-BASIC-2-5','除算の優先を保って括弧内の中置式を逆ポーランド記法へ変換する。',['ABC÷+DF−×','AB+C÷DF−×','ABC÷+D×F−','×+A÷BC−DF','AB+C÷D×F−'],['B÷Cの後にAを足し、D−Fの後に掛ける順に合う。','(A+B)÷Cへ括りを変えている。','左式×Dの後でFを引いてしまう。','先頭の演算子は後置ではない。','左の除算対象と最後の減算の括りが違う。'],1,'原典は(A+B÷C)×(D−F)である。左部分木はAとB÷Cを加えるのでABC÷+、右部分木はDF−。根の乗算を最後にしてABC÷+DF−×、1。OCRの減算らしい記号を採用せず原典の÷を保持する。','演算子の優先順位と後行順走査。','expression_tree_postorder',['theory:discrete:expression'],figure=True,calc=False,conditions={'原典式':'(A+B÷C)×(D−F)','OCR差':'生OCRの(A+B−C)は原典に一致しない。÷を別校正へ記録。'})
add('R03-REG-BASIC-2-6','漸近上界の定義から多項式・対数・指数・二重指数の四記述を判定する。',['正・誤・誤・誤','正・正・誤・正','正・正・正・誤','正・誤・正・誤','誤・誤・誤・正'],['対数と多項式、3/4の指数減衰を不適切に否定する。','ウは正でエは誤なので二か所が逆である。','ア・イ・ウの比は有界で、エは発散する。','イも正なので対数の成長を過大評価する。','四記述の判断が逆である。'],3,'アは(5nの3乗+1)/nの3乗≤6。イのlog2(n)/√nは0へ、ウのnの3乗×(3/4)のn乗も0へ収束する。エは2の(2のn乗)と10の(nの100乗)の比較で、比の対数は2のn乗ln2−nの100乗ln10となり正無限大へ発散する。従って正正正誤、3である。','Oは十分大きいnで定数倍に抑えられる上界である。対数・多項式・指数の比を調べる。','asymptotic_growth_order',['theory:discrete:asymptotic'],disc='basic_2_8',steps=3,load=2,diff=3,conditions={'ア':'5n^3+1=O(n^3)','イ':'n log2 n=O(n^1.5)','ウ':'n^3 3^n=O(4^n)','エ':'2^(2^n)=O(10^(n^100))'},cites=['mit_discrete2015'])
add('R04-REG-BASIC-2-2','四集合の包除原理から四重共通部分の要素数を逆算する。',['8','4','2','1','0'],['三重共通部分の一つ4より大きく包含条件にも反する。','包除式では和集合14となり条件16と違う。','44−42+16−2=16で条件に合う。','包除式で和集合17となる。','包除式で和集合18となる。'],3,'単集合は4通り、二重は6通り、三重は4通りなので、和集合16=4×11−6×7+4×4−x=18−x。x=2、3である。各交差が同じ値でも、一つだけ引いたり足したりせず組合せ数を掛ける。','四集合の包除と二重6・三重4の数え上げ。','set_inclusion_exclusion',['theory:discrete:inclusion'],cites=['mit_discrete2015'])
add('R07-REG-BASIC-2-1','直積集合を定義域とする全写像の数を積の法則で求める。',['12','36','64','81','128'],['6×2は定義域と像の組の総数であり写像数ではない。','6の2乗は方向を逆にした数え方である。','6要素の各像を独立に2択から選ぶ2の6乗である。','3の4乗は今回の定義域と値域の要素数に合わない。','2の7乗であり定義域要素を一つ多く数えている。'],3,'|A×B|=3×2=6である。各順序対の像をCの2要素から選ぶので、全写像は2の6乗=64、3である。単射・全射という条件はなく同じ像を複数の要素へ割り当ててよい。','直積の要素数と有限集合間の全写像数。','discrete_state_counts',['theory:discrete:mappings'])
add('R07-REG-BASIC-2-6','アッカーマン関数の二段の再帰を展開してA(2,2)を求める。',['7','8','9','10','11'],['A(1,n)=n+2、A(2,n)=2n+3より7である。','各再帰段の増分2と初期3を適用した7ではない。','n=3のA(2,3)=9でありnを一つ多くしている。','再帰の初期値又は増分の誤りである。','A(2,4)=11であり二段多く展開している。'],1,'A(1,0)=A(0,1)=2、A(1,n+1)=A(0,A(1,n))=A(1,n)+1なのでA(1,n)=n+2。A(2,0)=A(1,1)=3、A(2,n+1)=A(1,A(2,n))=A(2,n)+2。したがってA(2,1)=5、A(2,2)=7、1である。内側再帰の結果を外側の引数へ渡す。','非負整数の再帰基底と入れ子の引数評価。','ackermann_recursion',['theory:discrete:recursion'],steps=3,load=2,diff=3,conditions={'基底':'A(0,n)=n+1','零引数':'A(m+1,0)=A(m,1)','再帰':'A(m+1,n+1)=A(m,A(m+1,n))'})
